package com.sobrenaturaldirector.spatial.model;
import com.sobrenaturaldirector.domain.StableId;import com.sobrenaturaldirector.spatial.geometry.LocalAabb;
public final class SpatialConnectorPlacement {private final String placementId,sourceConnectorId,fromPlacementId,toPlacementId;private final LocalAabb volume;public SpatialConnectorPlacement(String id,String source,String from,String to,LocalAabb volume){placementId=StableId.require(id,"connectorPlacementId");sourceConnectorId=StableId.require(source,"sourceConnectorId");fromPlacementId=StableId.require(from,"fromPlacementId");toPlacementId=StableId.require(to,"toPlacementId");if(volume==null)throw new IllegalArgumentException("connector volume");this.volume=volume;}public String getPlacementId(){return placementId;}public String getSourceConnectorId(){return sourceConnectorId;}public String getFromPlacementId(){return fromPlacementId;}public String getToPlacementId(){return toPlacementId;}public LocalAabb getVolume(){return volume;}}
